model_safe_stan:
data {
  int<lower=1> N;
  vector[N] x;
  vector[N] y;

  int<lower=1> N_predict;
  array[N_predict] real x_predict;

  real<lower=0> sigma;
}

parameters {
  real c0;
  real c1;
  real c2;
  real c3;
}

model {
  vector[N] mu;

  c0 ~ normal(0, 10);
  c1 ~ normal(0, 2);
  c2 ~ normal(0, 0.01);
  c3 ~ normal(0, 0.01);

  for (n in 1:N) {
    mu[n] =   c0
            + c1 * x[n]
            + c2 * x[n] * x[n]
            + c3 * x[n] * x[n] * x[n];
  }

  y ~ normal(mu, sigma);
}

generated quantities {
  vector[N_predict] f;
  for (n in 1:N_predict) {
    f[n] =   c0
           + c1 * x_predict[n]
           + c2 * x_predict[n] * x_predict[n]
           + c3 * x_predict[n] * x_predict[n] * x_predict[n];
  }
}
